package io.reliablepush.notifications;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import tools.jackson.databind.JsonNode;

/**
 * Body of {@code POST /v1/notifications}. Unknown JSON fields are ignored; {@code policy} and {@code timeoutMinutes}
 * default per app. {@code trackingId} is required and generated by the sender; it is kept as text here and parsed by
 * {@link NotificationController}, so a missing or malformed one is a {@code 400} naming the field (sidecar revision
 * spec 2.1).
 */
public record RegisterNotificationRequest(
        String trackingId,
        @NotNull @Size(min = 1, max = 256) String userId,
        @Size(min = 1, max = 128) String externalId,
        FallbackPolicy policy,
        @Min(1) @Max(10080) Integer timeoutMinutes,
        @FallbackPayload JsonNode fallback) {}
